package com.familya.sharing.adapter.out.persistence;
import com.familya.sharing.application.port.out.ShareWatermarkRepository; import com.familya.sharing.domain.model.ShareLink; import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Component; import java.sql.Timestamp; import java.time.Instant; import java.util.*;
@Component public class JdbcAllowlistedProjectionRepository implements ShareWatermarkRepository {private final NamedParameterJdbcTemplate jdbc;private final ObjectMapper mapper=new ObjectMapper();public JdbcAllowlistedProjectionRepository(NamedParameterJdbcTemplate j){jdbc=j;}public long watermark(UUID t){var r=jdbc.queryForList("SELECT MAX(watermark) w FROM share_allowlisted_projection WHERE tree_id=:t",Map.of("t",t.toString()));return r.isEmpty()||r.get(0).get("w")==null?0:((Number)r.get(0).get("w")).longValue();}public void update(UUID t,long w,long v){}public Optional<Map<String,Object>> projection(UUID t,ShareLink.Scope s,UUID id){var r=jdbc.queryForList("SELECT allowlisted_json FROM share_allowlisted_projection WHERE tree_id=:t AND scope=:s AND target_id <=> :id",new MapSqlParameterSource().addValue("t",t.toString()).addValue("s",s.name()).addValue("id",id==null?null:id.toString()));if(r.isEmpty())return Optional.empty();try{return Optional.of(mapper.readValue((String)r.get(0).get("allowlisted_json"),new TypeReference<>(){}));}catch(Exception e){throw new IllegalStateException(e);}}public void saveProjection(UUID t,ShareLink.Scope s,UUID id,Map<String,Object> value,long w){try{jdbc.update("INSERT INTO share_allowlisted_projection(tree_id,scope,target_id,allowlisted_json,watermark,last_updated) VALUES(:t,:s,:id,:j,:w,:u) ON DUPLICATE KEY UPDATE allowlisted_json=:j,watermark=:w,last_updated=:u",new MapSqlParameterSource().addValue("t",t.toString()).addValue("s",s.name()).addValue("id",id==null?"":id.toString()).addValue("j",mapper.writeValueAsString(value)).addValue("w",w).addValue("u",Timestamp.from(Instant.now())));}catch(Exception e){throw new IllegalStateException(e);}}}
